*{box-sizing:border-box} :root{--bg:#080d16;--panel:#101924;--panel2:#121f2c;--line:#263545;--muted:#758596;--text:#e9f1f7;--gold:#e7ad56;--cyan:#69d5de;--red:#e46b72;--font-display:'Barlow Condensed',Impact,sans-serif;--font-body:'DM Sans',sans-serif}html,body{margin:0;min-height:100%;background:#080d16;color:var(--text);font-family:var(--font-body)}body{min-height:100vh;background:radial-gradient(ellipse at 50% -30%,#24384b 0,transparent 58%),linear-gradient(160deg,#0b121d 0%,#080d16 65%);overflow-x:hidden}.game-shell{max-width:1600px;margin:auto;padding:0 40px}.topbar{height:78px;border-bottom:1px solid #263441;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px;color:#e8eef2;text-decoration:none;font:800 21px var(--font-display);letter-spacing:1.6px}.brand b{color:var(--gold)}.brand-mark{width:34px;height:34px;display:grid;place-items:center;border:1px solid #bd944f;border-radius:50%;color:var(--gold);font-size:21px;box-shadow:0 0 18px #dca74522}.season-tag{color:#8f9eaa;font:600 11px var(--font-body);letter-spacing:1.7px}.season-tag span,.live-dot{display:inline-block;width:6px;height:6px;background:#d7a24c;border-radius:50%;margin:0 8px 1px 0;box-shadow:0 0 9px #e8ad56}.top-actions{display:flex;align-items:center;gap:12px}.icon-btn{width:34px;height:34px;background:#131e2a;border:1px solid #293745;border-radius:8px;color:#a6b6c3;font-size:17px;cursor:pointer}.icon-btn:hover{color:var(--gold);border-color:#9c7943}.pilot{display:flex;align-items:center;gap:10px;margin-left:12px}.pilot-avatar{width:36px;height:36px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(145deg,#244052,#152638);border:1px solid #4a6878;color:#8ee4e6}.pilot b,.pilot small,.player-card b,.player-card small{display:block}.pilot b{font:700 12px var(--font-display);letter-spacing:1.2px}.pilot small{font-size:9px;color:#8192a0;letter-spacing:1.1px;margin-top:3px}.match-layout{display:grid;grid-template-columns:205px minmax(500px,1fr) 205px;gap:24px;padding-top:24px;align-items:start}.side-panel{padding-top:12px}.panel-kicker,.intel-title{font:700 12px var(--font-display);letter-spacing:1.8px;color:#8f9dab;margin-bottom:16px}.player-card{display:flex;align-items:center;gap:9px;min-height:63px;padding:10px;background:linear-gradient(110deg,#142130,#101923);border:1px solid #2b3a49;border-radius:7px}.player-card b{font:700 12px var(--font-display);letter-spacing:.8px}.player-card small{color:#758796;font-size:8px;letter-spacing:.8px;margin-top:4px}.player-card strong{margin-left:auto;font:800 22px var(--font-display);color:#eab35c}.player-avatar{flex:none;width:34px;height:34px;display:grid;place-items:center;border-radius:6px;font-size:18px}.rebel{background:#1b3943;color:#68d9d8;border:1px solid #34606a}.empire{background:#3d242d;color:#e88184;border:1px solid #75404a}.opponent{border-color:#49343b}.opponent strong{color:#e57c7c}.vs-divider{height:37px;display:flex;align-items:center;gap:9px;padding:0 8px;color:#677786;font:800 12px var(--font-display)}.vs-divider span{height:1px;background:#293744;flex:1}.objective-box{display:flex;gap:10px;margin-top:26px;padding:12px 10px;background:#121d28;border:1px solid #253441;border-radius:6px}.objective-icon{flex:none;width:26px;height:26px;display:grid;place-items:center;color:#e4b25f;border:1px solid #715e3d;border-radius:50%;font-size:15px}.objective-box b,.tips-box>span{font:700 11px var(--font-display);letter-spacing:1.1px;color:#d4a857}.objective-box p{margin:5px 0 0;color:#9cabb6;font-size:10px;line-height:1.5}.objective-box em{font-style:normal;color:#e5e9eb}.tips-box{margin-top:19px;padding:12px;border-left:2px solid #4d7884;background:#0d1721}.tips-box>span{font-size:10px;color:#77c7ce}.tips-box p{font-size:10px;color:#91a1ac;line-height:1.55;margin:6px 0 0}.battle-column{min-width:0}.arena-wrap{border:1px solid #344858;border-radius:9px;background:#0c141e;overflow:hidden;box-shadow:0 14px 44px #0005}.arena-head{height:64px;background:linear-gradient(90deg,#172430,#101923 70%,#1b2025);display:flex;align-items:center;justify-content:space-between;padding:0 19px;border-bottom:1px solid #2c3b47}.arena-name,.opponent-mini{display:flex;align-items:center;gap:10px}.planet-icon{width:35px;height:35px;display:grid;place-items:center;border:1px solid #80643e;color:#e6ad58;border-radius:50%;font-size:20px}.arena-name b,.opponent-mini b{display:block;font:800 13px var(--font-display);letter-spacing:1.25px}.arena-name small,.opponent-mini small{display:block;color:#80909e;font-size:8px;letter-spacing:1.25px;margin-top:3px}.match-clock{text-align:center}.match-clock small{display:block;font:700 8px var(--font-body);color:#90a0aa;letter-spacing:1.4px}.match-clock strong{display:block;font:800 27px var(--font-display);letter-spacing:1px;color:#f1be68;line-height:1.1}.opponent-mini{min-width:150px;justify-content:flex-end}.enemy-mini-avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#39252d;color:#eb8381;border:1px solid #66404a;font-size:18px}.canvas-box{position:relative;width:100%;height:min(56vw,550px);min-height:370px;background:#27343a;overflow:hidden}.canvas-box canvas{width:100%;height:100%;display:block;touch-action:none;cursor:crosshair}.arena-hint{position:absolute;bottom:12px;left:50%;transform:translateX(-50%);white-space:nowrap;padding:7px 12px;border:1px solid #d5c29340;border-radius:20px;background:#111b20bb;color:#e5cf9f;font:700 9px var(--font-body);letter-spacing:1.1px;pointer-events:none;transition:opacity .4s}.arena-hint span{font-size:12px;margin-right:5px}.toast{position:absolute;top:15px;left:50%;transform:translate(-50%,-10px);opacity:0;background:#111b25e8;border:1px solid #c9994d;color:#f4d18e;padding:9px 16px;border-radius:5px;font:700 11px var(--font-display);letter-spacing:1px;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.pause-overlay{position:absolute;inset:0;background:#09111bd9;display:none;place-items:center;backdrop-filter:blur(4px)}.pause-overlay.active{display:grid}.pause-overlay>div{display:flex;align-items:center;flex-direction:column;gap:9px}.pause-overlay span{font-size:26px;color:var(--gold)}.pause-overlay b{font:900 29px var(--font-display);letter-spacing:3px}.pause-overlay small{color:#9ba9b2}.pause-overlay button{margin-top:12px;padding:11px 22px;color:#111923;background:var(--gold);border:0;border-radius:4px;font:800 12px var(--font-display);letter-spacing:1px;cursor:pointer}.arena-foot{height:27px;background:#101923;display:flex;align-items:center;justify-content:space-between;padding:0 13px;color:#788b98;font:700 8px var(--font-body);letter-spacing:1.1px}.online-dot{display:inline-block;width:5px;height:5px;background:#6cceaa;border-radius:50%;margin-right:5px}.ping{color:#667a89}.command-bar{display:grid;grid-template-columns:147px minmax(0,1fr) 54px;gap:13px;margin-top:15px;padding:13px;background:linear-gradient(130deg,#141f2b,#101822);border:1px solid #2a3946;border-radius:8px}.energy-top{display:flex;justify-content:space-between;align-items:center}.energy-top>div{display:grid;grid-template-columns:23px auto;align-items:center}.energy-symbol{grid-row:span 2;color:#65d4dc;font-size:19px}.energy-top b{font:800 13px var(--font-display);letter-spacing:1px}.energy-top>div small{font-size:8px;color:#82929c;letter-spacing:1.2px}.energy-top strong{font:800 22px var(--font-display);color:#6dd3dc}.energy-top strong small{font:600 10px var(--font-body);color:#78909a}.energy-track{position:relative;height:9px;margin:10px 0 7px;background:#08121b;border:1px solid #2e4651;border-radius:8px;overflow:hidden}.energy-track>div:first-child{width:50%;height:100%;background:linear-gradient(90deg,#368895,#76e5e3);box-shadow:0 0 10px #62dce477;transition:width .2s}.energy-ticks{position:absolute;inset:0;display:flex;justify-content:space-between}.energy-ticks i{height:100%;width:1px;background:#08121b}.energy-note{display:flex;justify-content:space-between;color:#80919c;font-size:8px;letter-spacing:.6px}.energy-note span:last-child{font-size:7px;color:#56bfc5}.deck-area{min-width:0}.deck-label{height:16px;display:flex;align-items:flex-start;justify-content:space-between;font:800 10px var(--font-display);letter-spacing:1.4px;color:#c5d0d5}.deck-label small{font:600 7px var(--font-body);letter-spacing:.8px;color:#718391}.card-row{display:flex;gap:7px;height:99px}.unit-card{position:relative;min-width:0;flex:1;border:1px solid #3c5260;border-radius:5px;background:#172634;overflow:hidden;text-align:center;cursor:pointer;transition:transform .15s,border-color .15s,filter .15s;color:#eaf1f2}.unit-card:hover{transform:translateY(-3px);border-color:#e0b15d}.unit-card.selected{border:2px solid #f0c46d;box-shadow:0 0 14px #ebbc5760;transform:translateY(-4px)}.unit-card.unaffordable{filter:grayscale(.7) brightness(.65)}.card-art{height:56px;display:flex;align-items:center;justify-content:center;position:relative;background:radial-gradient(ellipse at 50% 70%,#528a9a55,transparent 60%),linear-gradient(145deg,#243d4a,#162431)}.unit-card:nth-child(2) .card-art{background:radial-gradient(ellipse at 50% 70%,#bd574955,transparent 60%),linear-gradient(145deg,#47313b,#222530)}.unit-card:nth-child(3) .card-art{background:radial-gradient(ellipse at 50% 70%,#d19c4a55,transparent 60%),linear-gradient(145deg,#55452e,#282c30)}.unit-card:nth-child(4) .card-art{background:radial-gradient(ellipse at 50% 70%,#7268bd55,transparent 60%),linear-gradient(145deg,#39374e,#1e2732)}.unit-emoji{font-size:27px;filter:drop-shadow(0 3px 4px #0008);line-height:1}.card-cost{position:absolute;top:4px;left:5px;width:19px;height:19px;border-radius:50%;display:grid;place-items:center;background:#57aab1;border:1px solid #a2f4ea;color:white;font:800 11px var(--font-display);box-shadow:0 1px 6px #0008}.card-name{display:block;font:800 11px var(--font-display);letter-spacing:.35px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:3px 2px 0}.card-role{display:block;color:#82939d;font-size:7px;letter-spacing:.55px;margin-top:1px}.next-slot{text-align:center;color:#82939b;font:700 8px var(--font-body);letter-spacing:1px}.next-card-preview{width:43px;height:59px;margin:8px auto 0;border:1px solid #3a4b58;border-radius:4px;background:linear-gradient(145deg,#22313d,#111a23);display:grid;place-items:center;font-size:21px;opacity:.8}.footnote{text-align:center;color:#71818d;font:700 8px var(--font-body);letter-spacing:1.25px;padding:12px 0}.footnote span{color:#dfae5b;font-size:12px;vertical-align:-1px;margin-right:5px}.intel-title{display:flex;align-items:center;gap:8px;margin-bottom:17px}.intel-title span{color:#d8aa5e;font-size:17px}.stat-box{padding:12px 10px;margin-bottom:8px;background:#121d28;border:1px solid #263744;border-radius:5px}.stat-box>span{display:block;font:700 9px var(--font-body);letter-spacing:1.1px;color:#84949e}.stat-box>strong{display:block;margin-top:4px;font:800 22px var(--font-display);color:#e1e9ed;letter-spacing:.5px}.control-track{height:6px;background:#9c5356;border-radius:6px;margin:11px 0 7px;overflow:hidden}.control-track i{display:block;width:50%;height:100%;background:#57c2c1;transition:width .4s}.stat-box>small{font-size:8px;color:#84949e;letter-spacing:.8px}.log-title{display:flex;justify-content:space-between;margin:19px 0 9px;font:800 11px var(--font-display);letter-spacing:1.4px;color:#b9c5ca}.log-title span{color:#e98476;font:700 8px var(--font-body);letter-spacing:1px}.combat-feed{min-height:85px;max-height:160px;overflow:auto}.feed-item{display:flex;align-items:flex-start;gap:6px;padding:7px 0;border-bottom:1px solid #1d2b37;color:#94a3ac;font-size:9px;line-height:1.4}.feed-item i{color:#e0ad5a;font-style:normal}.feed-item time{margin-left:auto;white-space:nowrap;color:#657582;font-size:7px}.feed-item.enemy i{color:#e07c7c}.side-bottom{margin-top:24px}.callout{display:flex;gap:9px;padding:11px 9px;background:#16232a;border:1px solid #31515a;border-radius:5px}.callout>span{font-size:19px;color:#79d3d5}.callout p{margin:0}.callout b,.callout small{display:block}.callout b{font:800 10px var(--font-display);letter-spacing:.8px;color:#96d6d4}.callout small{margin-top:4px;color:#8da0a6;font-size:8px;line-height:1.4}.concede-btn{width:100%;margin-top:11px;padding:9px;background:transparent;border:1px solid #49353c;border-radius:4px;color:#a57a7c;font:700 9px var(--font-display);letter-spacing:1px;cursor:pointer}.concede-btn:hover{background:#391e25;color:#ee9999}.page-footer{height:46px;display:flex;align-items:center;justify-content:space-between;color:#556571;font:700 8px var(--font-body);letter-spacing:1px}.page-footer i{font-style:normal;color:#ba8d4a;margin:0 5px}.page-footer b{color:#65cad0;font-size:13px;vertical-align:-1px}
@media(max-width:1100px){.game-shell{padding:0 20px}.match-layout{grid-template-columns:165px minmax(470px,1fr);gap:17px}.right-panel{display:none}.canvas-box{height:min(58vw,520px)}.side-panel{padding-top:10px}.command-bar{grid-template-columns:125px minmax(0,1fr) 46px;gap:9px;padding:10px}.unit-card{flex:1}.card-row{gap:5px}}
@media(max-width:720px){.game-shell{padding:0 10px}.topbar{height:56px}.brand{font-size:17px;gap:7px}.brand-mark{width:28px;height:28px;font-size:17px}.season-tag,.pilot,.top-actions .icon-btn:first-child{display:none}.top-actions{gap:6px}.top-actions .icon-btn{width:31px;height:31px}.match-layout{display:block;padding-top:9px}.left-panel{display:none}.arena-wrap{border-radius:6px}.arena-head{height:51px;padding:0 10px}.arena-name b{font-size:11px}.arena-name small,.opponent-mini small{font-size:7px}.planet-icon{width:30px;height:30px;font-size:16px}.match-clock strong{font-size:22px}.match-clock small{font-size:7px}.opponent-mini{min-width:unset;gap:6px}.opponent-mini b{font-size:10px}.enemy-mini-avatar{width:29px;height:29px;font-size:15px}.canvas-box{height:clamp(300px, calc(100dvh - 274px), 510px);min-height:300px}.arena-foot{font-size:7px;padding:0 8px}.command-bar{grid-template-columns:80px minmax(0,1fr) 40px;gap:7px;margin-top:8px;padding:8px}.energy-top>div{grid-template-columns:18px auto}.energy-symbol{font-size:15px}.energy-top b{font-size:11px}.energy-top>div small{font-size:7px}.energy-top strong{font-size:19px}.energy-top strong small{font-size:8px}.energy-note span:last-child{display:none}.energy-track{margin:8px 0 6px}.deck-label{font-size:9px}.deck-label small{font-size:6px}.card-row{height:90px;gap:4px}.card-art{height:50px}.unit-emoji{font-size:23px}.card-cost{width:17px;height:17px;font-size:10px}.card-name{font-size:10px}.card-role{font-size:6px}.next-card-preview{width:37px;height:53px;font-size:19px}.next-slot{font-size:7px}.footnote{font-size:7px;padding:8px 0}.page-footer{height:30px;font-size:6px}.arena-hint{font-size:8px;padding:6px 10px}.toast{width:max-content;max-width:90%;font-size:10px}}
@media(max-width:400px){.opponent-mini b{font-size:9px}.arena-name b{font-size:10px}.match-clock small{letter-spacing:.6px}.command-bar{grid-template-columns:70px minmax(0,1fr) 35px;gap:5px;padding:6px}.card-row{gap:3px}.card-name{font-size:9px}.deck-label small{font-size:5px}.arena-foot{letter-spacing:.4px}}

(() => {
  const canvas = document.getElementById('battlefield');
  const ctx = canvas.getContext('2d');
  const cardRow = document.getElementById('cardRow');
  const cards = {
    luke: { name: 'LUKE', role: 'JEDI KNIGHT', cost: 4, icon: '⚔️', hp: 170, damage: 38, range: 42, speed: 30, rate: .8, color: '#67d8e6', kind: 'hero' },
    han: { name: 'HAN SOLO', role: 'BLASTER ACE', cost: 3, icon: '🔫', hp: 100, damage: 24, range: 120, speed: 33, rate: 1.05, color: '#6fd4cb', kind: 'ranged' },
    chewie: { name: 'CHEWIE', role: 'WOOKIEE TANK', cost: 5, icon: '🐻', hp: 280, damage: 35, range: 37, speed: 22, rate: 1.05, color: '#dfa65e', kind: 'tank' },
    artoo: { name: 'R2-D2', role: 'ASTROMECH', cost: 2, icon: '🤖', hp: 85, damage: 16, range: 105, speed: 26, rate: .75, color: '#83d7ee', kind: 'support' },
    xwing: { name: 'X-WING', role: 'STARFIGHTER', cost: 4, icon: '✈️', hp: 135, damage: 32, range: 140, speed: 44, rate: 1.2, color: '#9be3db', kind: 'air' },
    storm: { name: 'STORMTROOPERS', role: 'IMPERIAL SQUAD', cost: 3, icon: '☠️', hp: 96, damage: 21, range: 105, speed: 28, rate: 1.1, color: '#f08c85', kind: 'ranged' },
    vader: { name: 'VADER', role: 'SITH LORD', cost: 5, icon: '🟥', hp: 230, damage: 43, range: 43, speed: 25, rate: .85, color: '#fb666c', kind: 'hero' },
    atst: { name: 'AT-ST', role: 'WALKER', cost: 5, icon: '🦿', hp: 250, damage: 33, range: 110, speed: 20, rate: 1.25, color: '#db8980', kind: 'tank' },
    tie: { name: 'TIE FIGHTER', role: 'FIGHTER WING', cost: 3, icon: '✦', hp: 90, damage: 24, range: 125, speed: 42, rate: .95, color: '#e98981', kind: 'air' }
  };
  const deck = ['luke', 'han', 'chewie', 'artoo', 'xwing'];
  let hand = deck.slice(0, 4), deckIndex = 4, selected = null;
  let units = [], towers = [], effects = [], particles = [];
  let energy = 5, elapsed = 0, matchTime = 180, last = 0, aiTimer = 4.5;
  let deployCount = 0, paused = false, ended = false, overtime = false, soundOn = false;
  let toastTimer = 0, hintTimer = 8, playerCrowns = 0, enemyCrowns = 0, frame = 0;
  const $ = id => document.getElementById(id);
  const clamp = (n, a, b) => Math.max(a, Math.min(b, n));

  function resize() {
    const rect = canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(rect.width * dpr); canvas.height = Math.round(rect.height * dpr);
    ctx.setTransform(canvas.width / 900, 0, 0, canvas.height / 600, 0, 0);
  }
  window.addEventListener('resize', resize); resize();

  function makeTower(side, x, y, type, lane) {
    const command = type === 'command';
    return { side, x, y, type, lane, hp: command ? 980 : 590, maxHp: command ? 980 : 590, range: command ? 185 : 160, damage: command ? 34 : 24, cooldown: Math.random() * .4, alive: true };
  }
  function freshGame() {
    units = []; effects = []; particles = []; energy = 5; elapsed = 0; matchTime = 180; last = 0; aiTimer = 3.6;
    deployCount = 0; paused = false; ended = false; overtime = false; selected = null; playerCrowns = 0; enemyCrowns = 0; hand = deck.slice(0, 4); deckIndex = 4;
    towers = [makeTower('enemy', .23, .16, 'guard', 0), makeTower('enemy', .77, .16, 'guard', 1), makeTower('enemy', .5, .095, 'command', 2), makeTower('player', .23, .84, 'guard', 0), makeTower('player', .77, .84, 'guard', 1), makeTower('player', .5, .905, 'command', 2)];
    $('combatFeed').innerHTML = '<div class="feed-item start"><i>✦</i><span>Squad deployed. Awaiting your orders, Commander.</span><time>NOW</time></div>';
    $('pauseOverlay').classList.remove('active'); $('pauseBtn').textContent = 'Ⅱ'; $('phaseLabel').textContent = 'BATTLE IN PROGRESS';
    $('arenaHint').style.opacity = '1'; hintTimer = 8; $('toast').classList.remove('show'); updateHud(); renderCards();
  }

  function addFeed(message, enemy = false) {
    const item = document.createElement('div'); item.className = `feed-item${enemy ? ' enemy' : ''}`;
    item.innerHTML = `<i>${enemy ? '◈' : '✦'}</i><span>${message}</span><time>NOW</time>`;
    $('combatFeed').prepend(item); while ($('combatFeed').children.length > 5) $('combatFeed').lastElementChild.remove();
  }
  function showToast(message) {
    const el = $('toast'); el.textContent = message; el.classList.add('show'); toastTimer = 1.7;
  }
  function renderCards() {
    cardRow.innerHTML = '';
    hand.forEach((id, i) => {
      const c = cards[id], card = document.createElement('button');
      card.className = `unit-card${selected === i ? ' selected' : ''}${energy < c.cost ? ' unaffordable' : ''}`;
      card.setAttribute('aria-label', `${c.name}, costs ${c.cost} energy. Select card.`);
      card.innerHTML = `<span class="card-art"><span class="unit-emoji">${c.icon}</span><span class="card-cost">${c.cost}</span></span><span class="card-name">${c.name}</span><span class="card-role">${c.role}</span>`;
      card.addEventListener('click', () => {
        if (ended || paused) return;
        selected = selected === i ? null : i;
        if (selected !== null && energy < c.cost) showToast('NOT ENOUGH FORCE ENERGY');
        else if (selected !== null) { showToast(`DEPLOY ${c.name.toUpperCase()} ON YOUR SIDE`); $('arenaHint').style.opacity = '1'; hintTimer = 4; }
        renderCards();
      });
      cardRow.appendChild(card);
    });
    const next = cards[deck[deckIndex % deck.length]];
    $('nextCard').textContent = next.icon;
  }

  function deploy(id, x, y, enemy = false) {
    const c = cards[id];
    if (!enemy && energy < c.cost) { showToast('NOT ENOUGH FORCE ENERGY'); return false; }
    if (!enemy) { energy -= c.cost; deployCount++; $('unitsDeployed').textContent = String(deployCount).padStart(2, '0'); }
    const count = id === 'storm' ? 3 : 1;
    for (let i = 0; i < count; i++) {
      const offset = count === 1 ? 0 : (i - 1) * .028;
      units.push({ id, side: enemy ? 'enemy' : 'player', x: clamp(x + offset, .07, .93), y: clamp(y + (enemy ? -offset : offset), .06, .94), hp: c.hp, maxHp: c.hp, damage: c.damage, range: c.range / 600, speed: c.speed / 600, rate: c.rate, cooldown: .15 + Math.random() * .35, target: null, kind: c.kind, color: c.color, icon: c.icon, lane: x < .5 ? 0 : 1, dead: false, bob: Math.random() * 6.28, hitFlash: 0 });
    }
    if (!enemy) {
      selected = null; const played = hand.shift(); hand.push(deck[deckIndex++ % deck.length]);
      renderCards(); addFeed(`${c.name} deployed to the field.`); $('arenaHint').style.opacity = '0';
    } else addFeed(`${c.name} spotted in the canyon!`, true);
    effects.push({ x, y, life: .65, max: .65, type: 'deploy', color: enemy ? '#fa7978' : '#72dcdf' });
